static uint32_t menu_get(uint32_t row)
{
    const menu_flag_t *f = menu_flag(row);
    uint32_t i = 0;
    if (f)
        return ((ui_prefs | (uint32_t)ui_rec_prefs << 8) & f->bit) != 0;
    switch (row) {
    case MI_COLOR: return cpal_on() ? NPALETTES : settings.palette % NPALETTES;   /* ((Skiff #27) CUSTOM: last) */
    case MI_PHEAD: return ui_ph_line != 0;
    case MI_LOWCUT: return settings.lowcut % 3u;
    case MI_HOLD: return settings_hold % 4u;
    case MI_SCROFF: return scr_get();
    case MI_CLICK: case MI_CLKLVL: case MI_COUNTIN: return rp_get(row - MI_CLICK);
    case MI_CLOCK: return (uint32_t)song.g[G_CLOCK] % NELEM(N_CLOCK);
    case MI_ROUTE: return song.g[G_ROUTE] != 0;
    case MI_TCH1: case MI_TCH2: case MI_TCH3: case MI_TCH4: case MI_TCH5: case MI_TCH6: return trk_midi_ch(row - MI_TCH1);
    case MI_HINTS: return ui_hints_off != 0;
    case MI_PREVIEW: return PREVIEW_SET ? 1u : 0u;
    case MI_RETURN: return ret_mode();
    case MI_TUNE: return (uint32_t)clamp(song.g[G_TUNE] + 50, 0, 100);
#if FELUCCA_CPU2
    case MI_CPU: return CPU2_SET ? 1u : 0u;            /* ((Skiff 1.3) 1 CORE, 2 CORES (BETA): from the next power-on) */
#endif
    case MI_CLK: return CLK320_SET ? 1u : 0u;          /* ((Skiff) 360 MHZ, 320 MHZ: from the next power-on) */
#if BOARD_SMK37
    case MI_KVEL: return SMK_KV_BYTE % SMK_KV_N;
#endif
    case MI_LEDS:
        while (i + 1u < LEDS_COUNT && LEDS_MENU[i] != settings_leds)
            i++;
        return i;
    }
    return 0;
}

static uint32_t sid_p(uint32_t sid)            /* P_COUNT: not one of ours */
{
    return sid < SID_E0 ? sid : sid < SID_E0 + 8u ? P_E0 + (sid - SID_E0) : sid < SID_COUNT ? sid - 8u : P_COUNT;
}

/* 155-byte voice -> 128-byte packed record (7-bit bytes: it travels in SysEx as it is) */
static void fm6_pack(const uint8_t *v, uint8_t *b)
{
    uint32_t k, i;
    for (k = 0; k < 6u; k++) {
        const uint8_t *o = v + k * FP_OP;
        uint8_t *d = b + k * 17u;
        for (i = 0; i < 11u; i++)
            d[i] = o[i] & 0x7Fu;
        d[11] = (uint8_t)((o[FP_LC] & 3u) | (o[FP_RC] & 3u) << 2);
        d[12] = (uint8_t)((o[FP_RS] & 7u) | (o[FP_DET] & 15u) << 3);
        d[13] = (uint8_t)((o[FP_AMS] & 3u) | (o[FP_KVS] & 7u) << 2);
        d[14] = o[FP_OL] & 0x7Fu;
        d[15] = (uint8_t)((o[FP_MODE] & 1u) | (o[FP_FC] & 31u) << 1);
        d[16] = o[FP_FF] & 0x7Fu;
    }
    for (i = 0; i < 9u; i++)
        b[102 + i] = v[FP_PR1 + i] & 0x7Fu;
    b[110] &= 31u;
    b[111] = (uint8_t)((v[FP_FB] & 7u) | (v[FP_OKS] & 1u) << 3);
    for (i = 0; i < 4u; i++)
        b[112 + i] = v[FP_LFS + i] & 0x7Fu;
    b[116] = (uint8_t)((v[FP_LKS] & 1u) | (v[FP_LFW] & 7u) << 1 | (v[FP_LPMS] & 7u) << 4);
    b[117] = v[FP_TRNSP] & 0x7Fu;
    for (i = 0; i < 10u; i++)
        b[118 + i] = v[FP_NAME + i] & 0x7Fu;
}

static void project_capture(project_t *p)
{
    uint32_t i;
    uint32_t f = motion_guard();
    memset(p, 0, sizeof *p);
    p->magic = PROJ_MAGIC;
    p->size = sizeof *p;
    for (i = 0; i < G_COUNT; i++)
        p->g[i] = song.g[i];
    p->sel = song.sel;
    p->parts = PROJ_PARTS;
    p->phys = PROJ_PHYS;
#if FELUCCA_LEGACY
    chain_defaults(&p->chain);                    /* (phase 5: no project-slot song; an empty one) */
#endif
    for (i = 0; i < NTRK; i++) {
        for (uint32_t j = 0; j < P_COUNT; j++) p->t[i].p[j] = motion_base_value(&trk[i], j);
        p->t[i].engine = trk[i].eng_req;
        p->t[i].preset = trk[i].preset;
        p->t[i].user = (uint8_t)(user_of(&trk[i]) < UP_SLOTS ? user_of(&trk[i]) + 1u : 0u);   /* ((2.0, #20)) */
#if FELUCCA_LEGACY
        memcpy(p->t[i].step, trk[i].step, sizeof trk[i].step);   /* (SKF3, SKF4 write neither: the patterns hold them) */
#endif
        fm6_pack(fm6_patch[i], p->fm6[i]);
    }
#if FELUCCA_LEGACY
    p->motion = motion;
#endif
    motion_unguard(f);
    memcpy(p->name, proj_name, str_len(proj_name));
    memcpy(p->ent, lists.ent, sizeof p->ent);      /* (phase 5) each track's list, the entry it is on, SONG */
    memcpy(p->snd, lists.snd, sizeof p->snd);      /* ((2.0, #30) the entries' sounds) */
    memcpy(p->cur, lists.cur, sizeof p->cur);
    p->song = lists.song;
    memcpy(p->scene, lists.scene, sizeof p->scene);  /* (the scenes too: the project's) */
    if (memcmp(dx_kit, DX_KIT_DEF, sizeof dx_kit)) {   /* (phase 7) the DRUM-X kit, when not the factory's (none: */
        p->dx_on = 1;                              /* the factory's when loaded; a project of before as it was) */
        memcpy(p->dx, dx_kit, sizeof p->dx);
    }
    p->sum = proj_sum(p);
}

