/* (2.0, #34, the user's pick 2A) a copy's number: the first free after its original's (06's copy is 08 when 07 is
 * used), round to the first free before it, ((#44) none of taken's: a chain's copies before it); NPAT: the pool full */
static uint32_t pool_free_after(uint32_t orig, uint64_t taken)
{
    uint32_t i, id;
    for (i = 1; i <= BK_POOL; i++) {
        id = (orig + i) % BK_POOL;
        if (!pool_used(id) && pend_at(id) == PEND_N && !((taken >> id) & 1u))
            return id;
    }
    return NPAT;
}

static void ed_load_after(const ed_load_t *b)
{
    uint32_t i;
    if (!ed_w.on || b->due)
        return;
    sync_reload = 0;
    ed_w.eng = (uint8_t)ed_eng(TSEL);
    ed_w.preset = TSEL->preset;
    for (i = 0; i < P_COUNT; i++)                        /* the load's values; a pending push of another stays */
        if (TSEL->p[i] != b->p[i])
            ed_w.v[i] = TSEL->p[i];
}

/* slot k -> the selected part's sound: engine and every parameter except the track's own (param_kept:
 * the mix, ARP, SCL, the pattern parameters, the SLICER). The steps stay. 0 ok, 1 empty, 2 refused: (Skiff phase 6)
 * an engine the track may not play (said; nothing changes) */
static int up_load(uint32_t k)
{
    const up_rec_t *r;
    int16_t v[P_COUNT];
    uint32_t i;
    track_t *t = TSEL;
    if (!up_used(k))
        return 1;
    if (!eng_allowed(song.sel, up_engine(k))) {
        eng_refused(up_engine(k));
        return 2;
    }
    r = up_rec(k);
    up_values(r, v);
    load_begin(t, UNDO_SOUND);                          /* (ui.c: the copy for SAVE held = undo) */
    panic_req |= (uint8_t)(1u << song.sel);
#if !FELUCCA_FM4 && FELUCCA_LEGACY
    if (r->engine == ENGI_DIGITAL) {                    /* a DIGITAL sound (kept as it was stored): FM6 */
        int16_t p[P_COUNT];
        for (i = 0; i < P_COUNT; i++)
            p[i] = param_kept(i) ? t->p[i] : v[i];
        fm4_apply(t, p);
    } else
#endif
    {
        fm1_irq_off();                                  /* the audio ISR must not see half a sound */
        t->eng_req = r->engine;
        for (i = 0; i < P_COUNT; i++)
            if (!param_kept(i))
                t->p[i] = v[i];
        t->preset = 0;
        fm1_irq_on();
        upf_track_load(t, k);                           /* FM6: the preset's own patch (up_fm6.c) */
    }
    t->user = (uint8_t)(k + 1u);
    load_end(t);
    sync_reload = 1;
    ui.force = 1;
    return 0;
}

