static void con_dec(int32_t v)
{
    char b[12];
    uint32_t n = 0, u = v < 0 ? (uint32_t)-v : (uint32_t)v;
    if (v < 0)
        con_putc('-');
    do
        b[n++] = (char)('0' + u % 10u);
    while ((u /= 10u) != 0 && n < sizeof b);
    while (n)
        con_putc(b[--n]);
}

static void con_hex(uint32_t v, uint32_t digits)
{
    while (digits--)
        con_putc("0123456789ABCDEF"[(v >> (digits * 4u)) & 15u]);
}

static int ml_drop(uint32_t cc, uint32_t k, uint32_t id)
{
    uint32_t i, gone = 0;
    for (i = 0; i < ML_N; i++)
        if (ml_tab[3u * i] && (ml_tab[3u * i + 1u] == cc || ml_is(i, k, id))) {
            ml_put(i, 0, 0, 0);
            gone = 1;
        }
    return gone;
}

/* OCT+ with LFO held (lfo) or FX's layer open (fx): their values stay as they are now, held or on their way back (FX:
 * also its ALL OFF, the menu: perf_k cleared by the caller); 1: some */
static int mom_keep(int lfo, int fx)
{
    uint32_t i, k = 0;
    for (i = 0; i < mom.n; i++)
        if (!(mom_fx(&mom.e[i]) ? fx : lfo))
            mom.e[k++] = mom.e[i];
    i = mom.n != k;
    mom.n = (uint8_t)k;
    return (int)i;
}

/* the tails of cnt notes: o[i]'s out, p[i] tied on n[i] of the next part's first steps (CT_SAME: as many as o[i]'s);
 * last (the part's last step unfolded; 0 none): a tail of a pitch not sounding there goes too (a note deleted, moved,
 * shortened). Written: the record waiting to be kept (pat_keep_rec), its copy staged to come in the same. 0 done, 1 no
 * next part, 2 no room for all of a tail (it goes as far as it can) */
static int chain_tails(uint32_t k, const step_t *last, uint32_t cnt, const uint8_t *o, const uint8_t *p, const uint8_t *n)
{
    step_t u[CT_N];
    uint8_t l[4];
    uint32_t e2, un, id, i, j, ch = 0;
    int rc = 0;
    launch_t *q = &launch_q[k % NTRK];
    if ((id = chain_next(k, &e2, u, &un)) == PAT_NONE)
        return 1;
    for (i = 0; i < cnt && i < 4u; i++) {
        l[i] = (uint8_t)tail_len(u, un, o[i]);
        tail_out(u, un, o[i]);
        ch |= l[i];
    }
    for (i = 0; last && i < u[0].n;)               /* (a tail of a pitch not at the part's end) */
        if (step_tied(&u[0], i) && note_at(last, u[0].note[i]) < 0) {
            tail_out(u, un, u[0].note[i]);
            ch = 1;
        } else
            i++;
    for (i = 0; i < cnt && i < 4u; i++)
        for (j = 0; j < (n[i] == CT_SAME ? l[i] : n[i]); j++, ch = 1)
            if (j >= un || !ed_add(&u[j], p[i], 1)) {
                rc = 2;
                break;
            }
    if (!ch)
        return rc;
    for (i = 0; i < un; i++)
        if (!step_put9(bk_rec + BK_STEPS + i * 9u, &u[i]))
            return 2;
    bk_rec[0] = BK_VER3;                           /* (ties in it) */
    if (pat_keep_rec(id, bk_rec))
        return 2;
    if (q->armed && q->slot == e2 && !q->done) {   /* (playing: the copy coming in next, the same) */
        fm1_irq_off();
        for (i = 0; i < un; i++) {
            u[i].nudge = q->step[i].nudge;
            q->step[i] = u[i];
        }
        fm1_irq_on();
    }
    bk.gen++;
    return rc;
}

/* the lanes step s strikes: its hits, and its notes on their lanes (a NOTE step only) */
static uint32_t step_lanes(const step_t *s)
{
    uint32_t m = 0, i;
    if (s->time != ST_NOTE)
        return 0;
    for (i = 0; i < s->n && i < 4u; i++)
        m |= 1u << drum_lane(s->note[i]);
    return m | s->hit;
}

/* a knob turned parameter id of track t (ui_input.c, ui_layer.c): picked while learning */
static void ml_knob(const track_t *t, uint32_t id)
{
    if (!ui.ml.on || id >= P_COUNT)
        return;
    ui.ml.trk = (uint8_t)trk_index(t);
    ui.ml.id = (uint8_t)id;
    ui.ml.pick = 1;
    ml_heard = 0;
    ml_arm = 1;
    ui.foot_sig = 0;
}

/* id has a row's name on track t: motion records it, and the track's sound has it (DRUM's lane levels on a DRUM
 * track, the engine's own E1..E8 that it labels; not DIGITAL's operators, retired) */
static int ev_id_ok(const track_t *t, uint32_t id)
{
    const param_desc_t *d;
    if (id >= P_COUNT || !motion_param(id) || id == P_ED_FX || (id >= P_FM1_ATK && id <= P_FM4_LEVEL))
        return 0;
    if (id >= P_LN0 && id <= P_LN7)
        return drum_track(t);
    if (id >= P_LTUNE0 && id <= P_LDECAY7)            /* ((Skiff phase 9) the lanes' TUNE and DECAY: DRUM's own) */
        return t->eng_req % NENGINES == ENGI_DRUM;
    d = track_desc(t, id);
    return d && d->label && d->label[0] && d->label[0] != '-' && d->max > d->min;
}

/* slice j of DIV div: [*a, *b), *st the state at *a */
static void slc_bounds(const slc_src_t *s, uint32_t div, uint32_t j, uint32_t *a, uint32_t *b, uint32_t *st)
{
    const slc_man_t *m = div == SLC_DIV_MAN ? slc_man_of(s) : 0;
    if (div < SLC_DIV_AUTO) {
        uint32_t w = SLC_GRID >> (2u + div);
        *a = slc_gpos(s, j * w);
        *b = slc_gpos(s, (j + 1u) * w);
        *st = s->grid[j * w];
    } else if (m) {
        j = j < m->n ? j : m->n - 1u;
        *a = m->pos[j];
        *b = j + 1u < m->n ? m->pos[j + 1u] : slc_man_end(s, m);
        *st = m->st[j];
    } else {
        j = j < s->nauto ? j : s->nauto - 1u;
        *a = s->apos[j];
        *b = j + 1u < s->nauto ? s->apos[j + 1u] : s->len;
        *st = s->ast[j];
    }
}

