/* (Skiff U3, N3, N5) a family's first page the track has; NPAGES: none */
static uint32_t page_vis_first(uint32_t fam)
{
    uint32_t i;
    for (i = 0; i < NPAGES; i++)
        if (PAGES[i].fam == fam && page_visible(i))
            return i;
