}

/* (1.2.1, #6) SAVE > PROJECT's DELETE: the slot emptied, in flash (an empty record: st_load reads 0) and in its RAM copy
 * (.noinit, kept over a warm reset; persist_boot and project_load read the flash only when it is empty). The music
 * playing stays; if it was this slot's it is on no slot now, and unknown counts as changed (project_dirty: nothing is
 * lost without a question). Patterns only it named stay in the pool, unused (PATTERNS can clear them).
 * 0 done, 1 refused (playing, an empty slot), 2 failed (the slot as it was) */
static int project_erase(uint32_t slot)
{
    slot &= 3u;
    if (transport_busy()) {
        ui_message("STOP TO DELETE");
        return 1;
    }
    if (!project_used(slot)) {
        ui_message("EMPTY SLOT");
        return 1;
    }
#if FELUCCA_FLASH
    if (flash_ok && st_save(OBJ_PROJECT0 + slot, &proj_wire, 0)) {
        ui_message("DELETE ERROR");
        return 2;
    }
#endif
    memset(&proj_slot[slot], 0, sizeof proj_slot[slot]);
    if (proj_cur == slot) {
        proj_cur = PROJ_NO_SLOT;
        pj_clean = autosave_sig() + 1u;
        pj_at = 0;
    }
#if FELUCCA_FLASH
    if (flash_ok) { ui_message("PROJECT DELETED"); return 0; }
#endif
    ui_message("DELETED UNTIL POWER OFF");
    return 0;
}

/* .. (the user's pick 2A) the track's sound as an entry's (b): its user sound or factory preset, as it was loaded (its
 * values, an FM6 patch, a DRUM-X preset's kit as they came); 0: none such (edited since: SAVE > USER keeps it as a user
 * sound; an FM6 patch of its own, a sample set of the user's: the same) */
static int snd_of(uint32_t k, uint8_t *b)
{
    esnd_t s;                                      /* (the main loop's stack: 448 B, once) */
    const track_t *t = &trk[k % NTRK];
    uint32_t i, u = user_of(t);
    b[0] = (uint8_t)(u < UP_SLOTS ? 0x80u | u : t->eng_req + 1u);
    b[1] = (uint8_t)(u < UP_SLOTS ? 0u : t->preset);
    if (!esnd_make(k, b, &s))
        return 0;
    for (i = 0; i < P_COUNT; i++)
        if (!param_kept(i) && motion_base_value(t, i) != s.p[i])
            return 0;
    if (s.fm6 && memcmp(fm6_patch[k % NTRK], s.f6, FP_SIZE))
        return 0;
    return !s.kit || !memcmp(dx_kit, DX_KITS[s.kit - 1u], sizeof dx_kit);
}

/* the effects that can run at the tempo: a REPEAT / REVERSE longer than the loop cannot */
static uint32_t perf_avail(void)
{
    uint32_t e, m = ~0u, b = beat_samples();
    for (e = PF_R8; e <= PF_REV; e++)
        if (b > PB_MAX * PF_DEN[e])
            m &= ~PF_BIT(e);
    return m;
}

/* a key hint: the keycap, then what it does (S, TEXT); unavailable: a DIM keycap and a DIM word. The word sits on
 * the keycap's centre line (S caps 9 rows, the keycap's 7). act may be 0 (the keycap alone); returns the end x */
#define KH_GAP 4                                  /* keycap -> its word */
/* (Skiff) BLOCKS: a hint is one line of words, "KEY: WHAT", as the mockup's PRESETS: STEP */
static void kh_plain(char *b, uint32_t n, uint32_t id, const char *act)
{
    uint32_t k = kc_cat(b, 0, n, KC[id < KC_COUNT ? id : 0u].label);
    if (act && act[0])
        kc_cat(b, kc_cat(b, k, n, ": "), n, act);
}

static uint32_t str_hash(uint32_t h, const char *s)
{
    while (*s)
        h = (h ^ (uint8_t)*s++) * 16777619u;
    return h;
}

static void lower_words(char *s)                      /* a sentence the UI wrote (counts, words): the B mockup's case */
{
    for (; *s; s++)
        if (*s >= 'A' && *s <= 'Z')
            *s = (char)(*s + 32);
}

/* value string (<= 5 chars) and unit for a parameter value */
static void param_format(const param_desc_t *d, int32_t v, char *val, const char **unit)
{
    *unit = "";
    fmt_named = d->fmt == F_ENUM;
    switch (d->fmt) {
    case F_PCT:                                     /* a 0..100 range (SWG) is its value, others a share of 127 */
        fmt_int(val, d->max == 100 ? v : (v * 100 + 63) / 127);
        *unit = "%";
        break;
    case F_BIPCT:                                   /* -64..63 as -100..+100 % (Felucca #199: each side over its own
                                                     * range; up to Skiff 1.2 / 64 both ways, the top read +98) */
        fmt_int(val, v * 100 / 64);
        if (v > 0) {
            char t[8];
            fmt_int(t, v * 100 / 63);
            val[0] = '+';
            str_cpy(val + 1, t, 6);
        }
        *unit = "%";
        break;
    case F_TIME: {
        uint32_t ms10 = TIME_MS_X10[v & 127];
        if (ms10 < 100u) {
            fmt_fix(val, (int32_t)ms10, 1);
            *unit = "ms";
        } else if (ms10 < 10000u) {
            fmt_int(val, (int32_t)((ms10 + 5u) / 10u));
            *unit = "ms";
        } else {
            fmt_fix(val, (int32_t)(ms10 / 100u), 2);
            if (ms10 >= 100000u)
                fmt_fix(val, (int32_t)(ms10 / 1000u), 1);
            *unit = "s";
        }
        break;
    }
    case F_LFOHZ: {
        uint32_t h = LFO_HZ_X100[v & 127];
        if (h < 1000u)
            fmt_fix(val, (int32_t)h, 2);
        else
            fmt_fix(val, (int32_t)(h / 10u), 1);
        *unit = "Hz";
        break;
    }
    case F_CUTOFF: {
        uint32_t h = CUTOFF_HZ[v & 127];
        if (h < 1000u) {
            fmt_int(val, (int32_t)h);
            *unit = "Hz";
        } else {
            fmt_fix(val, (int32_t)(h / 100u), 1);
            *unit = "kHz";
        }
        break;
    }
    case F_DB:
        if (v <= 0) {
            str_cpy(val, "OFF", 6);
        } else {
            fmt_fix(val, LEVEL_DB_X10(v), 1);
            *unit = "dB";
        }
        break;
    case F_SEMI:
        fmt_int(val, v);
        if (v > 0) {
            char t[8];
            fmt_int(t, v);
            val[0] = '+';
            str_cpy(val + 1, t, 6);
        }
        *unit = "st";
        break;
    case F_ENUM:
        str_cpy(val, d->names[v < d->min ? d->min : v > d->max ? d->max : v], 8);   /* ((Skiff U4, V5) 7 letters: the
                                                       * card falls to M, then S, where V is too wide) */
        if (d->unit)
            *unit = PD_UNIT_OF(d);
        break;
    case F_BPM:
        fmt_int(val, v);
        *unit = "BPM";
        break;
    case F_NOTE:
        str_cpy(val, N_NOTE[v % 12], 6);
        break;
    case F_ONOFF:
        str_cpy(val, N_ONOFF[v ? 1 : 0], 6);
        break;
    case F_STEPS:
        fmt_int(val, v);
        *unit = "STEP";
        break;
    case F_ST16: {                                  /* (Skiff U1) +-12 semitones in 3/16 steps, to 0.1: "+3.2" */
        int32_t t = (v - 64) * 30, a;               /* (tenths x 16, rounded half away from 0) */
        char *q = val;
        t = (t + (t < 0 ? -8 : 8)) / 16;
        a = t < 0 ? -t : t;
        if (t)
            *q++ = t < 0 ? '-' : '+';
        fmt_int(q, a / 10);
        q += str_len(q);
        q[0] = '.';
        q[1] = (char)('0' + a % 10);
        q[2] = 0;
        *unit = "st";
        break;
    }
    default:
        if (d->names) {                               /* F_INT with a 0-terminated name list: the range */
            uint32_t k = 0;                           /* split evenly over the names (engine desc hooks) */
            while (d->names[k])
                k++;
            str_cpy(val, d->names[(uint32_t)(clamp(v, d->min, d->max) - d->min) * k / (uint32_t)(d->max - d->min + 1)], 6);
        } else {
            fmt_int(val, v);
        }
        if (d->unit)
            *unit = PD_UNIT_OF(d);
        break;
    }
}

static uint32_t param_icon(const param_desc_t *d, int32_t v)
{
    uint32_t i;
    if (!d)
        return ICON_NONE;
    if (d->fmt == F_ENUM && d->names && v >= d->min && v <= d->max &&
        (str_eq(d->label, "WAVE") || str_eq(d->label, "WAVE2")))
        for (i = 0; i < sizeof(WAVE_ICON) / sizeof(WAVE_ICON[0]); i++)
            if (str_eq(d->names[v], WAVE_ICON[i].label))
                return WAVE_ICON[i].icon;
    if (d == &TP[P_LWAVE])
        return ICON_LFO_WAVE;                 /* "WAVE" is also the oscillator wave */
    if (d == &TP[P_ARATE] || d == &TP[P_SLRATE])
        return ICON_DIVISION;                 /* arp / SLICER RATE is a note division, not Hz */
    if (d->names == N_TRIO_MODE)
        return ICON_CUTOFF;                   /* TRIO's MODE is the filter type, not the arp mode */
    if (d->names == N_FMODE)
        return ICON_TRANSPOSE;                /* ((2.1) FOLLOW's MODE: how the notes move, not the arp mode) */
    if (d == &TP[P_FOLLOW])
        return ICON_SCALE;                    /* ((2.1) the track whose chords it follows, as CHORD's) */
    if (d->names == N_NOISE_MODE)
        return ICON_NOISE;                    /* NOISE's MODE is the source; its CLK the register clock */
    if (d == &NOISE_CLK)
        return ICON_RATE;
#if FELUCCA_SLICE
    if (d->names == N_SLC_DIV)
        return ICON_SLICE;                    /* SLICE: DIV is the slicing, MODE the gate, REV the direction */
    if (d->names == N_SLC_MODE)
        return ICON_GATE;
    if (d->names == N_SLC_REV)
        return ICON_ORDER;
#endif
    return icon_for_label(d->label);
}

static uint8_t dx_ui_seen = 0xFFu, dx_ui_hits;     /* the last key note followed, the strikes counted then */
/* a key struck on the track (seq.c last_note) picks the lane it plays: *lane (the sheet's, ui_dx.c; (2.0, #36) LANE
 * MIX's); ((2.0) the same key struck again too: last_hits) */
static void lane_follow(uint8_t *lane)
{
    if (last_note != dx_ui_seen || last_hits != dx_ui_hits) {
        if (dx_ui_seen != 0xFFu)                     /* (the first look only takes note of it) */
            *lane = (uint8_t)drum_lane(last_note);
        dx_ui_seen = last_note;
        dx_ui_hits = last_hits;
    }
}

/* parameter locks: a page whose KNOB 1..4 can lock (a track's sound: one of its parameters can be motion; not MOD's
 * slots), the parameter KNOB k locks (ui.plk_src's page, HOME's four), 0xFF = none */
/* (2.0, D 1A) a fixed MOD route doing nothing on the track's engine (dimmed): the LFO to PITCH CUT SHAPE on the hits
 * (DRUM, DRUM-X: AMP does), the ENV's on the hits and where the operators are the envelope (FM6): LFO DEST's dimmed
 * cards and ENV DEST's hidden page of before */
static int mod_dead(const track_t *t, uint32_t r)
{
    const engine_t *e = ENGINES[t->eng_req % NENGINES];
    return r < 3u ? e->oneshot : r >= 4u && r < MOD_SLOT0 && (e->oneshot || e->ownenv);
}

/* the part's voice mode: P_VOICE, POLY for an engine of hits (engine_t.oneshot: DRUM) */
static uint32_t trk_vmode(const track_t *t)
{
    return ENGINES[t->engine]->oneshot ? V_POLY : (uint32_t)t->p[P_VOICE];
}

/* a dotted ring round (cx, cy), radius r, n dots */
static void qk_dotring(int32_t cx, int32_t cy, int32_t r, uint32_t n, uint16_t c)
{
    uint32_t k;
    for (k = 0; k < n; k++) {
        uint32_t ph = k * (0xFFFFFFFFu / n);
        cv_rect(cx + r * QK_COS(ph) / 32767, cy + r * QK_SIN(ph) / 32767, 1, 1, c);
    }
}

/* .. lane l of track t sounds: a user kit's has a sample (LANES and LANE MIX draw one without it empty); every other's */
static int drum_lane_has(const track_t *t, uint32_t l)
{
    uint32_t u = t->eng_req % NENGINES == ENGI_DRUM ? drum_user(t->p) : 0u;
    return !u || drum_user_zone(u - 1u, l) != 0u;
}

/* tanh(x / 32768) * 32767, linearly interpolated (a plain lookup gives
 * 256-unit steps, audible on quiet signals) */
static inline int32_t softclip(int32_t x)
{
    int32_t a = x < 0 ? -x : x, i = a >> 8, y;
    if (i >= 256)
        y = TANH_Q15[256];                           /* continuous with the table */
    else
        y = TANH_Q15[i] + (((TANH_Q15[i + 1] - TANH_Q15[i]) * (a & 255)) >> 8);
    return x < 0 ? -y : y;
}

/* (Skiff phase 9) FX > DRIVE: the TYPE's transfer at the DRIVE, as fx.c track_dist shapes it (its low cut and tone left
 * out): the input across, the output up, the straight line dim behind it; at the right the TYPE, DIST and TONE (CRUSH:
 * the bits left, the hold). (2.0, D 2A) INSERT's shapers (ins_shape), DT_* to IT_* */
static int32_t pg_drive_at(uint32_t type, int32_t d, int32_t x)
{
    static const uint8_t DT_IT[DT_N] = {IT_SOFT, IT_HARD, IT_FOLD, IT_CRUSH, IT_FUZZ};
    int32_t g = 4096 + d * d * 2, y = ((x >> 2) * g) >> 10;
    if (!d)
        return x;                                    /* (DIST 0: no DIST at all) */
    if (type == DT_CRUSH)
        return mulq15(ins_shape(IT_CRUSH, x, (uint32_t)d / 11u), 32000 - d * 20);
    y = type == DT_SOFT ? softclip(y + 2400) - softclip(2400) : ins_shape(DT_IT[type], y, 0);
    return mulq15(clamp(y, -40000, 40000), 30000 - d * 120);
}

/* a clean state for model md */
static void phys_reset(phys_slot_t *S, uint32_t md, uint32_t seed)
{
    uint32_t i, *w = (uint32_t *)&S->u;
    for (i = 0; i < sizeof S->u / 4u; i++)
        w[i] = 0;
    S->model = (uint8_t)md;
    seed |= 1u;
    switch (md) {
    case PM_STRING:
    case PM_SYMP:                                        /* (the main string is the union's px_string_t) */
        S->u.s.rng = seed;
        S->u.s.src = 1u << 30;
        break;
    default:
        S->u.m.rng = seed;
        break;
    }
}

/* sin(2 pi ph), ph a turn in Q32; Q30 (odd polynomial of the quarter wave, error ~4e-6) */
static int32_t px_sin(uint32_t ph)
{
    uint32_t q = ph >> 30, r = ph & 0x3FFFFFFFu;
    int32_t t, t2, p;
    if (q & 1u)
        r = 0x40000000u - r;
    t = (int32_t)r;
    t2 = px_m(t, t, 30);
    p = 172272;
    p = 5026995 - px_m(t2, p, 30);
    p = 85569306 - px_m(t2, p, 30);
    p = 693598668 - px_m(t2, p, 30);
    p = 1686629713 - px_m(t2, p, 30);
    p = px_m(t, p, 30);
    return q & 2u ? -p : p;
}

/* the string over n samples, excited by in[] (Q20): out[] */
static void px_string_run(const px_string_blk_t *B, px_string_t *S, const int32_t *in, int32_t *out, uint32_t n)
{
    uint32_t i, wp = S->wp, swp = S->swp, rs = S->rng;
    uint32_t src = S->src;
    int32_t o0 = S->out0, o1 = S->out1, lp = S->lp, disp = S->disp, bridge = S->bridge;
    int32_t dcx = S->dc_x, dcy = S->dc_y, dce = S->dc_e, ein = S->ein;
    for (i = 0; i < n; i++) {
        ein += in[i];                                    /* resampled: the input since the last step */
        /* the string */
        src += (uint32_t)B->src_ratio;
        if (src > 1u << 30) {
            uint32_t dl = (uint32_t)(((uint64_t)B->delay * (uint32_t)B->comp) >> 30);
            int32_t s;
            src -= 1u << 30;
            if (!B->curved) {
                int32_t nz = (int32_t)(px_rand(&rs) >> 12) - (1 << 19);   /* rand - 0.5 */
                disp += px_m(B->noise_flt, nz - disp, 30);
                dl = (uint32_t)(((uint64_t)dl * (uint32_t)((1 << 30) + px_m(disp, B->noise_amt, 20))) >> 30);
                {
                    uint32_t ap = (uint32_t)(((uint64_t)dl * (uint32_t)B->m_ap) >> 30);
                    uint32_t mn = (uint32_t)(((uint64_t)dl * (uint32_t)B->m_main) >> 30);
                    if (ap >= 4u << 16 && mn >= 4u << 16) {
                        uint32_t t = wp + (mn >> 16);
                        int32_t a = S->line[t & PX_LMASK], bb = S->line[(t + 1u) & PX_LMASK], rd, w;
                        s = a + px_m(bb - a, (int32_t)(mn & 0xFFFF), 16);
                        rd = S->sline[(swp + (ap >> 16)) & PX_SMASK];   /* DelayLine::Allpass */
                        w = s + px_m(B->ap_gain, rd, 30);
                        S->sline[swp] = w;
                        swp = (swp - 1u) & PX_SMASK;
                        s = rd - px_m(w, B->ap_gain, 30);
                    } else {
                        s = px_hermite(S->line, wp, dl);
                    }
                }
            } else {
                int32_t val, as;
                dl = (uint32_t)(((uint64_t)dl * (uint32_t)((1 << 30) - px_m(bridge, B->curving, 20))) >> 30);
                s = px_hermite(S->line, wp, dl);
                as = s < 0 ? -s : s;
                val = as - 26214;                        /* |s| - 0.025 */
                bridge = val > 0 ? (s > 0 ? 2 * val : -3 * val) : 0;
            }
            s = px_clamp(s + ein, -20 * PX_ONE, 20 * PX_ONE);
            ein = 0;
            {   /* DcBlock (with the rounding error fed back) */
                int64_t acc = (int64_t)1073498345 * dcy + dce;
                int32_t y = s - dcx + (int32_t)(acc >> 30);
                dce = (int32_t)(acc & 0x3FFFFFFF);
                dcx = s;
                dcy = y;
                s = y;
            }
            {   /* OnePole low-pass */
                int32_t v = px_m(B->G, s - lp, 30);
                s = lp + v;
                lp = s + v;
            }
            S->line[wp] = s;                             /* DelayLine::Write */
            wp = (wp - 1u) & PX_LMASK;
            o1 = o0;
            o0 = s;
        }
        out[i] = o1 + px_m(o0 - o1, (int32_t)src, 30);            /* CrossFade, linear */
    }
    S->wp = wp;
    S->swp = swp;
    S->rng = rs;
    S->src = src;
    S->out0 = o0;
    S->out1 = o1;
    S->lp = lp;
    S->disp = disp;
    S->bridge = bridge;
    S->dc_x = dcx;
    S->dc_y = dcy;
    S->dc_e = dce;
    S->ein = px_clamp(ein, -20 * PX_ONE, 20 * PX_ONE);
}

static void phys_render(track_t *t, voice_t *v, int32_t *out, uint32_t n, const vmod_t *m)
{
    const int16_t *p = t->p;
    phys_slot_t *S = phys_slot_of(t, v);
    uint32_t md = (uint32_t)p[P_E0] % PM_COUNT, i, f0 = m->inc;
    int32_t y[CTL], ax[CTL];
    int32_t strc = p[P_E1] * 516, brit = clamp(p[P_E2] * 516 + m->cutoff * 2, 0, 65536);   /* Q16 0..1 */
    int32_t damp = p[P_E3] * 516, pos = p[P_E4], exc = p[P_E7] * 258;   /* exc Q15 */
    int32_t bow = p[P_E6] * 206;                         /* BOW: Dust at up to 0.4 (DaisySP's sustain: 1) */
    int32_t acc = clamp(p[P_E5] * v->vel * 4, 0, 65536);   /* ACC at full velocity, Q16 */
    int32_t g = PHYS_GAIN[md];
    if (!S)
        return;
    if (n > CTL)
        n = CTL;
    if (S->model != md)                                  /* MODEL changed under a sounding note */
        phys_reset(S, md, PHYS_RSEED(t));
    switch (md) {
    case PM_MODAL: {
        px_modal_blk_t B;
        px_modal_block(&B, &S->u.m, f0, strc, brit, damp, acc, pos * 129, bow);   /* pos 0..1/4 */
        px_modal_run(&B, &S->u.m, y, ax, n);
        break;
    }
    case PM_MEMB: {
        px_modal_blk_t B;
        px_memb_block(&B, &S->u.m, f0, strc, brit, damp, acc, pos * 516, p[P_E6] * 6192);   /* BEND 0..12 st */
        px_modal_run(&B, &S->u.m, y, ax, n);
        break;
    }
    case PM_STRING: {
        px_string_blk_t B;
        px_string_block(&B, &S->u.s, f0, strc, brit, damp, acc, bow, pos * 516);   /* 0..1/2 period */
        px_string_excite(&B, &S->u.s, ax, n);
        px_string_run(&B, &S->u.s, ax, y, n);
        break;
    }
    default: {                                           /* SYMP */
        px_string_blk_t B;
        uint32_t f[PX_NSYMP];
        phys_symp_pitches(t, m, f);
        px_string_block(&B, &S->u.y.s, f0, 16384 - p[P_E6] * 129, brit, damp, acc, 0, 0);   /* BUZZ: STRC 0.25 .. 0 */
        px_string_excite(&B, &S->u.y.s, ax, n);
        px_string_run(&B, &S->u.y.s, ax, y, n);
        px_symp_block(&S->u.y, f, brit, damp, pos * 516);
        px_symp_run(&S->u.y, y, y, n);
        break;
    }
    }
    for (i = 0; i < n; i++) {
        int32_t s = px_m(y[i] + px_m(ax[i], exc, 15), g, 20), a = s < 0 ? -s : s;
        if (a > 24000) {                                 /* soft knee: only peaks saturate */
            a = 24000 + (softclip(clamp(a - 24000, 0, 1 << 20) * 2) >> 1);
            s = s < 0 ? -a : a;
        }
        out[i] += voice_amp(s, m, i) << 1;
    }
}

/* ------------------------------------------------------- patch formats --- */
/* the highest value of each byte of the 155-byte voice */
static uint32_t fm6_max(uint32_t i)
{
    static const uint8_t OPMAX[21] = {99, 99, 99, 99, 99, 99, 99, 99, 99, 99, 99, 3, 3, 7, 3, 7, 99, 1, 31, 99, 14};
    static const uint8_t VMAX[19] = {99, 99, 99, 99, 99, 99, 99, 99, 31, 7, 1, 99, 99, 99, 99, 1, 5, 7, 48};
    if (i < 126u)
        return OPMAX[i % 21u];
    if (i < FP_NAME)
        return VMAX[i - 126u];
    return 126u;
}

/* the operator tabs: OP1 .. OP6 outlined, the one picked in TEXT; under each its line's colour (a carrier's: the
 * ramp: it shows the heat); TONE: the ratio beside the number */
static void fm_tabs(const fm_sim_t *s, const uint16_t *sh, int ratios)
{
    uint32_t k, sel = fm_ui[0] % 6u;
    for (k = 0; k < 6u; k++) {
        int32_t x = 8 + (int32_t)k * 38;
        const uint8_t *op = fm6_patch[fm_tr()] + (5u - k) * FP_OP;
        int on = k == sel, live = s->live >> k & 1u;
        uint16_t ink = on ? T_TEXT : live ? T_MID : T_DIM;
        char b[8];
        if (ux.crypt || ux.neon) {                      /* ((FM6 LAB T) stone or glass; the one picked: a gold frame, */
            cv_rrect(x, 4, 34, 17, 3, T_SURF, T_SURF);  /* a laser; QUARK: a cell's brackets, the one picked gold) */
            if (on && ux.crypt)
                cr_frame2(x - 2, 2, 38, 21, CR_GOLD);
            else if (on)
                ne_laser(x, 4, 34, 17, T_SURF);
        } else if (ux.quark) {
            qk_corners(x, 4, 34, 17, on ? T_ACCENT : T_DIM, 5);
        } else {
            cv_frame(x, 4, 34, 17, on ? T_TEXT : T_DIM);
            if (on)
                cv_frame(x + 1, 5, 32, 15, T_TEXT);
        }
        if (ratios) {
            b[0] = (char)('1' + k);
            b[1] = 0;
            cv_text_on(x + 5, 4 + CAP_IN(S, 17), &AF_S, b, ink, T_SURF);
            if (op[FP_MODE])
                str_cpy(b, FM_HZ[op[FP_FC] & 3u], sizeof b);
            else if (op[FP_FC])
                fmt_int(b, op[FP_FC]);
            else
                str_cpy(b, ".5", sizeof b);
            str_cpy(b + str_len(b), op[FP_MODE] ? "" : "x", sizeof b - str_len(b));
            cv_text_r(x + 30, 4 + CAP_IN(S, 17), &AF_S, b, live ? T_MID : T_DIM, T_SURF);
            if (ux.crypt || ux.neon)                    /* ((FM6 LAB T) the pixel letters run together: a divider) */
                cv_rect(x + 12, 8, 1, 9, T_DIM);
        } else {
            b[0] = 'O', b[1] = 'P', b[2] = (char)('1' + k), b[3] = 0;
            GFX_HOOK_ALIGN(x, 4, x + 34, 21, AL_HV, "FM6 operator tab name centred");
            cv_text_in(x, 4 + CAP_IN(S, 17), 34, &AF_S, b, ink, T_SURF);
        }
        if (!live)
            continue;
        if (s->car >> k & 1u) {
            uint32_t j;
            for (j = 0; j < 12u; j++)
                cv_rect(x + 3 + (int32_t)j * 2 + (j > 5u) * 4, 23, 2, 2, sh[j]);
        } else
            cv_rect(x + 3, 23, 28, 2, T_TRK(k));
    }
}
